Party').click();saved=await page.evaluate(()=>({parties:JSON.parse(localStorage.getItem('imposter.parties')),active:localStorage.getItem('imposter.activeParty')}));assert(saved.parties.length===1&&saved.parties[0].name==='Fresh Start'&&saved.active===saved.parties[0].id,'new party flow failed after empty state');assert(await page.locator('#player-row').count()===0,'new party should start with no players');console.log('PARTIES',JSON.stringify({cancelWorks:true,fallback:'p1',rotationCleanup:true,emptyState:true,newParty:saved.parties[0].name,playerRows:await page.locator('.player-row').count()}));await page.close();
