/* Shared interaction and layout polish */
:focus-visible{outline:3px solid #9fc24d;outline-offset:3px}
button:disabled{opacity:.52;cursor:not-allowed;transform:none!important}
.primary-btn:disabled:hover{background:var(--green);color:var(--green-dark)}
.panel{min-width:0}
.phase-card h1 em,.stats-wrap .phase-head h1 em{font-style:normal;color:#98bd4b}
.party-bar{display:flex;align-items:end;gap:12px;padding:13px 15px;margin:-8px 0 17px;border:1px solid var(--line);border-radius:12px;background:#fffefa;box-shadow:var(--shadow)}
.party-bar>div{min-width:0;flex:1}
.party-bar .eyebrow{display:block;margin:0 0 5px 2px;font-size:9px}
.party-select{display:block;width:100%;height:39px;padding:0 35px 0 11px;border:1px solid var(--line);border-radius:8px;background:#fffefa;color:var(--ink);font-size:12px;font-weight:600;outline:none}
.party-select:focus{border-color:#9ab95b;box-shadow:0 0 0 3px #a8cc6026}
.party-bar .secondary-btn{height:39px;white-space:nowrap;padding:0 13px;font-size:10px}
.party-bar .mini-link{height:39px;white-space:nowrap;padding:0 8px}
.stats-panel{padding:clamp(18px,3vw,30px)}
.stats-wrap .phase-head h1{font:600 clamp(28px,4vw,40px)/1.1 'Space Grotesk',sans-serif;letter-spacing:-1.6px;margin:7px 0 0;overflow-wrap:anywhere}
.stats-toolbar{display:flex;align-items:center;justify-content:space-between;gap:15px;padding-bottom:19px;border-bottom:1px solid #f0eee9}
.stats-toolbar .phase-description{margin:5px 0 0;text-align:left}
.stats-toolbar .secondary-btn{height:40px;padding:0 13px;white-space:nowrap;font-size:10px}
.party-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:20px 0}
.party-summary>div,.stats-metrics>div{min-width:0;padding:15px 10px;border:1px solid #eeece6;border-radius:10px;background:#fbfaf6;text-align:center}
.party-summary strong,.stats-metrics strong{display:block;font:600 24px/1 'Space Grotesk',sans-serif;color:#36452b}
.party-summary span,.stats-metrics span{display:block;margin-top:8px;color:#8b9086;font:9px 'DM Mono',monospace;letter-spacing:.7px}
.stats-list{display:grid;gap:7px}
.stats-row{width:100%;min-width:0;display:grid;grid-template-columns:30px minmax(70px,1fr) minmax(110px,auto) auto;align-items:center;gap:10px;padding:11px 12px;border:1px solid #eeece6;border-radius:9px;background:#fffefa;color:var(--ink);text-align:left}
.stats-row:hover{border-color:#c5d89d;background:#f8faF3}
.stats-row strong{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
.stats-row>span:not(.stats-rank){color:#858a80;font-size:11px}
.stats-row b{font:500 11px 'DM Mono',monospace;color:#596d39;white-space:nowrap}
.stats-rank{height:26px;width:26px;display:grid;place-items:center;border-radius:8px;background:#f1f7e7;color:#6b8440;font:500 11px 'DM Mono',monospace}
.stats-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;padding:20px 0 10px}
.history-heading{display:flex;justify-content:space-between;align-items:center;margin-top:20px;padding:14px 0 9px;border-top:1px solid #f0eee9}
.history-heading h3{margin:0;font:600 12px 'Space Grotesk',sans-serif}
.history-heading span{color:#92968b;font:9px 'DM Mono',monospace;letter-spacing:.7px}
.history-list{display:grid;gap:7px}
.history-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:5px 12px;padding:11px 12px;border:1px solid #eeece6;border-radius:9px;background:#fffefa}
.history-row>div{min-width:0}
.history-row strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
.history-row small{display:block;margin-top:4px;color:#92968b;font-size:10px}
.history-row>small{grid-column:1/-1;margin:0}
.history-winner{padding:6px 8px;border-radius:99px;background:#f1f8e6;color:#627d35;font:9px 'DM Mono',monospace;white-space:nowrap}
.history-winner.imposter{background:#fff0eb;color:#bd654f}
