content.text:
.stats-row b{font:500 11px 'DM Mono',monospace;color:#596d39;white-space:nowrap}
.stats-rank{height:26px;width:26px;display:grid;place-items:center;border-radius:8px;background:#f1f7e7;color:#6b8440;font:500 11px 'DM Mono',monospace}
.stats-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;padding:20px 0 10px}
.history-heading{display:flex;justify-content:space-between;align-items:center;margin-top:20px;padding:14px 0 9px;border-top:1px solid #f0eee9}
.history-heading h3{margin:0;font:600 12px 'Space Grotesk',sans-serif}
.history-heading span{color:#92968b;font:9px 'DM Mono',monospace;letter-spacing:.7px}
.history-list{display:grid;gap:7px}
.history-row{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:5px 12px;padding:11px 12px;border:1px solid #eeece6;border-radius:9px;background:#fffefa}
.history-row>div{min-width:0}
.history-row strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}
.history-row small{display:block;margin-top:4px;color:#92968b;font-size:10px}
.history-row>small{grid-column:1/-1;margin:0}
.history-winner{padding:6px 8px;border-radius:99px;background:#f1f8e6;color:#627d35;font:9px 'DM Mono',monospace;white-space:nowrap}
.history-winner.imposter{background:#fff0eb;color:#bd654f}
.stats-footer{display:flex;justify-content:flex-end;margin-top:12px;border-top:1px solid #f0eee9;padding-top:10px}
.danger-text{color:#bd654f}
.category-label{margin-top:17px;font:500 9px 'DM Mono',monospace;letter-spacing:1.8px;color:#92968b}
.category-value{margin-top:4px;color:#788f48;font:600 13px 'DM Mono',monospace;letter-spacing:1.2px}
.starting-player-card{max-width:680px;margin:0 auto}
.starting-player-card>.eyebrow{color:#8b9b66}
.starting-player-name{color:#252e23}
.starting-player-name em{font-style:normal;color:#98bd4b}
.verbal-instruction{max-width:440px;margin:0 auto 13px;padding:15px 18px;border:1px solid #e8eddd;border-radius:10px;background:#f7faef;color:#68715e;font-size:13px;line-height:1.6}
.verbal-instruction strong{color:#3f4e2d}
.verbal-status{margin:0 auto 20px;color:#969a91;font-size:11px}
.start-discussion-row{margin-top:21px}
.start-discussion-row .primary-btn{max-width:330px}
.starting-player-card .timer{margin:27px 0;color:#242b24}
.starting-player-card .timer.urgent{color:var(--red)}
.starting-player-card .action-row{margin-top:20px}
.starting-player-card .action-row .primary-btn{max-width:330px}

@media(max-width:900px){
  .app-shell{padding-right:28px;padding-left:28px}
  .setup-grid{grid-template-columns:minmax(0,1fr)}
  .settings-panel{order:1}
  .players-panel{order:0}
  .player-list{max-height:300px}
}
@media(max-width:650px){
  .app-shell{padding-right:17px;padding-left:17px}
  main{padding-top:22px}
  .party-bar{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;margin:-4px 0 15px;padding:11px}
  .party-bar>div{grid-column:1/-1}
  .party-bar .secondary-btn{grid-column:1;grid-row:2}
  .party-bar .mini-link{grid-column:2;grid-row:2}
  .stats-toolbar{align-items:flex-start}
  .stats-toolbar .secondary-btn{max-width:125px;white-space:normal;line-height:1.25}
  .stats-row{grid-template-columns:27px minmax(0,1fr) auto;gap:8px;padding:10px}
  .stats-row>span:not(.stats-rank){grid-column:2;grid-row:2;font-size:10px}
  .stats-row b{grid-column:3;grid-row:1/3}
  .party-summary{gap:6px;padding:15px 0}
  .party-summary>div,.stats-metrics>div{padding:12px 5px}
  .party-summary strong,.stats-metrics strong{font-size:21px}
  .party-summary span,.stats-metrics span{font-size:8px;letter-spacing:.2px;line-height:1.4}
  .stats-metrics{gap:6px}
  .history-row{grid-template-columns:minmax(0,1fr) auto;gap:5px 7px;padding:10px}
  .history-winner{font-size:8px;padding:6px}
  .verbal-instruction{padding:13px 14px}
  .starting-player-card .phase-description{margin-bottom:20px}
  footer{gap:12px}
  footer span:last-child{text-align:right}
}
@media(max-width:390px){
  .app-shell{padding-right:12px;padding-left:12px}
  .party-bar{grid-template-columns:minmax(0,1fr);}
  .party-bar>div,.party-bar .secondary-btn,.party-bar .mini-link{grid-column:1;grid-row:auto}
  .party-bar .secondary-btn,.party-bar .mini-link{width:100%}
  .stats-toolbar{display:grid}
  .stats-toolbar .secondary-btn{max-width:none;width:100%}
  .party-summary strong,.stats-metrics strong{font-size:18px}
  .history-row{grid-template-columns:minmax(0,1fr)}
  .history-winner{justify-self:start}
  footer{height:auto;min-height:47px;padding:10px 0;font-size:7px}
}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition:none!important}}

