.verbal-instruction strong{color:#31543a}
.modal-card{border:1px solid #e1e7dd;border-radius:18px;background:#fffefa}
.modal-card textarea{border-color:#dce3d8}
.toast{background:#1e402c;box-shadow:0 12px 30px rgba(16,39,24,.24);border:1px solid rgba(255,255,255,.12)}
:focus-visible{outline:3px solid #83a94c;outline-offset:3px}
button:disabled{opacity:.62}

@media(max-width:900px){
  .setup-grid{grid-template-columns:minmax(0,1fr)}
  .settings-panel{order:1}
  .players-panel{order:0}
}
@media(max-width:650px){
  .app-shell{padding-right:17px;padding-left:17px}
  .topbar{height:68px}
