const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const page = targets.find(t => t.type === 'page' && t.url === 'http://127.0.0.1:8765/');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((ok, no) => { ws.onopen = ok; ws.onerror = no; });
let id = 0;
const pending = new Map();
ws.onmessage = e => { const m = JSON.parse(e.data); if (m.id && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } };
function call(method, params = {}) { return new Promise((resolve, reject) => { const n = ++id; pending.set(n, m => m.error ? reject(m.error) : resolve(m.result)); ws.send(JSON.stringify({ id: n, method, params })); }); }
async function ev(expression) { const r = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true }); if (r.exceptionDetails) throw new Error(r.exceptionDetails.text); return r.result.value; }
const sizes = [[360,640],[360,800],[393,852],[412,915]];
const report = [];
for (const [w,h] of sizes) {
  await call('Emulation.setDeviceMetricsOverride', { width:w, height:h, deviceScaleFactor:1, mobile:true, screenWidth:w, screenHeight:h });
  await ev('location.reload()'); await new Promise(r => setTimeout(r, 250));
  await ev(`state.phase='setup';state.players=Array.from({length:15},(_,i)=>'Player '+(i+1));if(!state.parties.length)state.parties=[makeParty('Test Party')];state.activePartyId=state.parties[0].id;state.parties[0].players=state.players;render()`);
  const metrics = await ev(`(()=>{const sel=s=>document.querySelector(s), rect=e=>e?{x:Math.round(e.getBoundingClientRect().x),y:Math.round(e.getBoundingClientRect().y),w:Math.round(e.getBoundingClientRect().width),h:Math.round(e.getBoundingClientRect().height),bottom:Math.round(e.getBoundingClientRect().bottom)}:null;const list=sel('.player-list');return {vw:innerWidth,vh:innerHeight,docW:document.documentElement.scrollWidth,hero:rect(sel('.hero-line')),party:rect(sel('.party-bar')),partySelect:rect(sel('#partySelect')),partyActions:[...document.querySelectorAll('.party-actions>*')].map(e=>({label:e.textContent.trim(),...rect(e)})),players:rect(sel('.players-panel')),settings:rect(sel('.settings-panel')),list:rect(list),listClient:list?.clientHeight,listScroll:list?.scrollHeight,listOverflow:getComputedStyle(list).overflowY,start:rect(sel('#startGame')),footer:rect(sel('footer')),order:[...document.querySelectorAll('.hero-line,.party-bar,.players-panel,.settings-panel,#startGame')].map(e=>e.className||e.id)} })()`);
  await ev(`(()=>{const l=document.querySelector('.player-list');l.scrollTop=l.scrollHeight;return l.scrollTop})()`);
  const scroll = await ev(`(()=>{const l=document.querySelector('.player-list');return {top:l.scrollTop,bottomVisible:l.getBoundingClientRect().bottom,documentOverflow:document.documentElement.scrollWidth>innerWidth}})()`);
  await ev("document.querySelector('#newParty').click()");
  const newModal = await ev(`(()=>{const m=document.querySelector('#partyModal'),c=m?.querySelector('.modal-card');return {shown:!!m,modal:c?{w:Math.round(c.getBoundingClientRect().width),h:Math.round(c.getBoundingClientRect().height),top:Math.round(c.getBoundingClientRect().top),bottom:Math.round(c.getBoundingClientRect().bottom)}:null,overflow:document.documentElement.scrollWidth>innerWidth}})()`);
  if (w===360 && h===640) await call('Page.captureScreenshot',{format:'png'}).then(async r=>{await import('node:fs/promises').then(fs=>fs.writeFile('/tmp/opencode/setup-party-modal.png',Buffer.from(r.data,'base64')))});
  await ev("document.querySelector('#cancelParty').click();document.querySelector('#deleteParty').click()");
  const deleteModal = await ev(`(()=>{const m=document.querySelector('#deletePartyModal'),c=m?.querySelector('.modal-card');return {shown:!!m,modal:c?{w:Math.round(c.getBoundingClientRect().width),h:Math.round(c.getBoundingClientRect().height),top:Math.round(c.getBoundingClientRect().top),bottom:Math.round(c.getBoundingClientRect().bottom)}:null,overflow:document.documentElement.scrollWidth>innerWidth}})()`);
  await ev("document.querySelector('#cancelDeleteParty').click()");
  report.push({size:`${w}x${h}`,metrics,scroll,newModal,deleteModal});
}
console.log(JSON.stringify(report,null,2));
ws.close();

